const slug = ($json.project_slug ?? $json['Project Slug'] ?? '').toString().trim().toLowerCase().replace(/[^a-z0-9-]/g, '');
if (!slug) throw new Error('Project Slug is required.');
const burnRaw = ($json.burn_subs ?? $json['Burn Subtitles'] ?? 'yes').toString();
const fontRaw = Number($json.subtitle_font_size ?? $json['Subtitle Font Size'] ?? 24);
const volRaw = Number($json.music_volume ?? $json['Music Volume'] ?? 0.15);
const opts = {
  slug,
  burn_subs: burnRaw === 'yes',
  font_size: Math.min(64, Math.max(10, Number.isFinite(fontRaw) && fontRaw > 0 ? fontRaw : 24)),
  music_file: ($json.music_file ?? $json['Music File (optional, inside music/)'] ?? '').toString(),
  music_volume: Number.isFinite(volRaw) && volRaw > 0 ? volRaw : 0.15,
};
return [{ json: { slug, payloadB64: Buffer.from(JSON.stringify(opts)).toString('base64') } }];

