const plan = JSON.parse($('Plan Render').first().json.stdout.trim());
function srtTime(sec) {
  const ms = Math.max(0, Math.round(sec * 1000));
  const h = Math.floor(ms / 3600000);
  const m = Math.floor((ms % 3600000) / 60000);
  const s = Math.floor((ms % 60000) / 1000);
  const milli = ms % 1000;
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')},${String(milli).padStart(3, '0')}`;
}
let t = 0;
const cues = [];
for (const shot of plan.shots) {
  const start = t;
  const end = t + shot.dur;
  t = end;
  const text = (shot.subtext ?? '').toString().trim();
  if (!text) continue;
  cues.push(`${cues.length + 1}\n${srtTime(start)} --> ${srtTime(end)}\n${text}\n`);
}
const srt = cues.join('\n');
const slug = plan.slug;
const destDir = '/home/node/files/films/' + slug;
const destPath = destDir + '/subs.srt';
const b64 = Buffer.from(srt, 'utf8').toString('base64');
const SIZE = 60000;
const nChunks = Math.max(1, Math.ceil(b64.length / SIZE));
const out = [];
for (let s = 0; s < nChunks; s++) {
  out.push({ json: {
    fileId: slug + '_subs', destDir, destPath, seq: s,
    isLast: (s === nChunks - 1) ? 1 : 0,
    chunkB64: b64.slice(s * SIZE, (s + 1) * SIZE),
  }});
}
return out;
